import React, { useEffect, useState } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:8080');

interface ChatComponentProps {
    userId: string;
    agencyId: string;
}

const ChatComponent: React.FC<ChatComponentProps> = ({ userId, agencyId }) => {
    const [messages, setMessages] = useState<{ senderId: string; messageContent: string }[]>([]);
    const [currentMessage, setCurrentMessage] = useState('');

    useEffect(() => {
        const room = `${userId}_${agencyId}`;// a unique room name is being created

        socket.emit('join_room', room);    //message to the server to join speciefied room
        socket.on('receive_message', (data) => {
            setMessages((prevMessages) => [...prevMessages, data]);
        });

        return () => {
            socket.emit('leave_room', room);
        };
    }, [userId, agencyId]);

    const sendMessage = async () => {
        if (currentMessage.trim()) {
            const newMessage = { senderId: userId, receiverId: agencyId, messageContent: currentMessage };


            socket.emit('send_message', { ...newMessage, room: `${userId}_${agencyId}` });


            try {
                await fetch('http://localhost:8080/app/sendMessage', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(newMessage),
                });
            } catch (error) {
                console.error('Error sending message to server:', error);
            }

            setMessages((prevMessages) => [...prevMessages, newMessage]);
            setCurrentMessage('');
        }
    };


    return (
        <div>
            <div>
                {messages.map((msg, index) => (
                    <div key={index}>
                        <strong>{msg.senderId === userId ? 'You' : 'Agency'}:</strong> {msg.messageContent}
                    </div>
                ))}
            </div>
            <input
                type="text"
                value={currentMessage}
                onChange={(e) => setCurrentMessage(e.target.value)}
                placeholder="Type a message"
            />
            <button onClick={sendMessage}>Send</button>
        </div>
    );
};

export default ChatComponent;
